INSERT INTO university (name, province, city, level, type, tags, introduction, address, website, phone, min_score, max_score, ranking, features) VALUES
('清华大学', '北京', '北京', '985', '综合', '双一流,C9联盟', '清华大学是中国著名高等学府，坐落于北京西北郊风景秀丽的清华园。', '北京市海淀区清华园1号', 'https://www.tsinghua.edu.cn', '010-62793001', 680, 720, 1, '工科实力雄厚，理工科优势明显'),
('北京大学', '北京', '北京', '985', '综合', '双一流,C9联盟', '北京大学创办于1898年，初名京师大学堂，是中国第一所国立综合性大学。', '北京市海淀区颐和园路5号', 'https://www.pku.edu.cn', '010-62751234', 675, 715, 2, '文理医工并重，综合实力强'),
('浙江大学', '浙江', '杭州', '985', '综合', '双一流,C9联盟', '浙江大学是一所历史悠久、声誉卓著的高等学府，坐落于中国历史文化名城、风景旅游胜地杭州。', '浙江省杭州市西湖区余杭塘路866号', 'https://www.zju.edu.cn', '0571-87951111', 660, 700, 3, '学科门类齐全，综合性强'),
('上海交通大学', '上海', '上海', '985', '综合', '双一流,C9联盟', '上海交通大学是我国历史最悠久、享誉海内外的著名高等学府之一。', '上海市闵行区东川路800号', 'https://www.sjtu.edu.cn', '021-34200000', 655, 695, 4, '工科强校，医学突出'),
('复旦大学', '上海', '上海', '985', '综合', '双一流,C9联盟', '复旦大学创建于1905年，原名复旦公学，是中国人自主创办的第一所高等院校。', '上海市杨浦区邯郸路220号', 'https://www.fudan.edu.cn', '021-65642222', 650, 690, 5, '文理医并重，人文社科强');
INSERT INTO major (university_id, name, category, degree, introduction, courses, employment_direction, employment_rate, duration, min_score, enrollment_number) VALUES
(1, '计算机科学与技术', '工学', '学士', '培养具有良好的科学素养，系统地掌握计算机科学与技术的基本理论、基本知识和基本技能。', '数据结构,算法设计,操作系统,计算机网络,数据库原理', '软件开发,系统架构,人工智能,数据分析', 98.5, 4, 685, 120),
(1, '电子信息工程', '工学', '学士', '培养具备电子技术和信息系统的基础知识，能从事各类电子设备和信息系统的研究、设计、制造。', '电路分析,信号与系统,数字电路,通信原理', '通信工程,电子设计,嵌入式开发', 97.2, 4, 680, 100),
(2, '经济学', '经济学', '学士', '培养具备比较扎实的经济学理论基础，熟悉现代经济学理论，比较熟练地掌握现代经济分析方法。', '微观经济学,宏观经济学,计量经济学,金融学', '金融分析,经济研究,投资顾问,政策分析', 96.8, 4, 675, 80),
(3, '软件工程', '工学', '学士', '培养适应计算机应用学科的发展，特别是软件产业的发展，具备计算机软件的基础理论、基本知识和基本技能。', '软件工程,数据库系统,Web开发,移动应用开发', '软件开发,项目管理,系统分析,测试工程', 98.0, 4, 665, 150);
INSERT INTO career (industry, position, description, trend, salary, requirements, related_majors, development_path, demand_index) VALUES
('互联网', '软件工程师', '负责软件系统的设计、开发、测试和维护工作。', '随着数字化转型加速，软件工程师需求持续旺盛，特别是在人工智能、云计算等新兴领域。', '15K-40K', '计算机相关专业本科及以上学历，熟练掌握至少一门编程语言，具备良好的算法和数据结构基础。', '计算机科学与技术,软件工程,信息工程', '初级工程师→中级工程师→高级工程师→技术专家/架构师', 95),
('金融', '金融分析师', '进行金融市场分析、投资策略制定和风险评估。', '金融科技快速发展，对复合型金融人才需求增加，特别是具备数据分析能力的专业人才。', '12K-35K', '金融、经济相关专业，具备CFA等专业资格证书优先，熟悉金融市场和投资工具。', '金融学,经济学,统计学', '分析师助理→分析师→高级分析师→投资经理', 85),
('教育', '中学教师', '从事中学阶段的教学和学生管理工作。', '教育改革深化，对高素质教师需求稳定，特别是STEM学科教师需求较大。', '8K-18K', '师范类专业或相关学科专业，具备教师资格证，热爱教育事业。', '师范类专业,学科专业', '教师→骨干教师→学科带头人→教研组长', 75),
('医疗', '临床医生', '从事疾病诊断、治疗和患者护理工作。', '人口老龄化加剧，医疗需求持续增长，优质医疗资源仍然紧缺。', '10K-30K', '医学专业本科及以上学历，具备执业医师资格证，临床经验丰富。', '临床医学,中医学', '住院医师→主治医师→副主任医师→主任医师', 88);
